export interface Options {
  baseUrl: string;
  timeoutMs?: number;
}

export async function request(path: string, opts: Options): Promise<Response> {
  const url = opts.baseUrl + path;
  return fetch(url);
}

export function join(a: string, b: string): string {
  return a.replace(/\/$/, '') + '/' + b;
}

