export interface Options {
  baseUrl: string;
  timeoutMs?: number;
}

export async function request(path: string): Promise<string> {
  const res = await fetch(path);
  return res.text();
}

export function join(a: string, b: string): string {
  return a.replace(/\/$/, '') + '/' + b;
}

